      'desktop.repoScanRoots': 'Các thư mục cần quét. Để trống để quét thư mục chính của bạn.',
      'desktop.repoScanExcludePaths': 'Bỏ qua các thư mục này và mọi thư mục con khi tìm kho mã.',
      timezone: 'Mã múi giờ IANA. Để trống để dùng múi giờ hệ thống.',
      'browser.useRealProfile':
        'Khi duyệt web cục bộ, Hermes dùng các tài khoản bạn đã đăng nhập. Hermes sao chép hồ sơ của trình duyệt mặc định (cookie, thông tin đăng nhập, tùy chọn) vào một bản chụp được quản lý rồi điều khiển bản chụp đó bằng Chromium đi kèm — hồ sơ đang dùng không bao giờ được mở trực tiếp và bản sao sẽ được làm mới từ hồ sơ đó mỗi lần chạy. Tùy chọn này cũng cho phép agent mở phiên cục bộ bằng hồ sơ thật theo yêu cầu, kể cả khi đã cấu hình backend trình duyệt đám mây. Chỉ hỗ trợ các trình duyệt Chromium (Chrome, Edge, Brave, Brave Origin, Chromium); nếu trình duyệt mặc định không dùng Chromium, Hermes sẽ hiển thị thông báo rõ ràng. Mặc định tắt.',
      'agent.imageInputMode': 'Kiểm soát cách gửi tệp đính kèm hình ảnh cho mô hình.',
      'agent.maxTurns': 'Giới hạn số lượt gọi công cụ trước khi Hermes dừng lần chạy.',
      'terminal.cwd': 'Thư mục dự án mặc định cho công việc với công cụ và terminal.',
